-- Пятиминутки (владелец, 02.11.2026): темы ежедневных пятиминуток по кругу,
-- «повторение — мать учения». Пока это пример, который владелец покажет
-- второму управляющему, поэтому статья видна только управляющим (admin) и
-- владельцу (boss): отдел 'Управляющие'.
--
-- До сих пор менеджеры видели в базе знаний всё. Теперь — всё, кроме статей
-- с отделом 'Управляющие'. Отдела с таким названием у сотрудников нет, так
-- что через my_department() их тоже никто не увидит.
--
-- Главный экран берёт тему дня из этой же статьи (нумерованные строки), так
-- что правка статьи сразу меняет и темы на главной.

drop policy if exists kb_articles_read on public.kb_articles;
create policy kb_articles_read on public.kb_articles for select using (
  depts is null
  or cardinality(depts) = 0
  or exists (select 1 from public.profiles p
              where p.user_id = auth.uid() and p.role in ('admin', 'boss'))
  or (not ('Управляющие' = any (depts))
      and exists (select 1 from public.profiles p
                   where p.user_id = auth.uid() and p.role = 'manager'))
  or public.my_department() = any (depts)
);

insert into public.kb_books (title, icon, sort_order)
select 'Пятиминутки', '🗣️', 7
 where not exists (select 1 from public.kb_books where title = 'Пятиминутки');

insert into public.kb_articles (book_id, title, content, depts, media, sort_order)
select b.id, 'Пятиминутки: темы на 28 дней', E'Пятиминутка каждый день перед сменой. Темы идут по кругу: каждая повторяется раз в месяц. Тема дня видна на главном экране.\n\nКАК ПРОВОДИТЬ (5 МИНУТ)\n• План на день — 1 мин: брони, банкеты, кто на какой зоне.\n• Стоп-лист и новинки — 1 мин: чего нет, что продвигаем сегодня.\n• Объявления — 1 мин.\n• Тема дня — 2 мин: ведущий не читает, а спрашивает «Расскажи, как ты делаешь…», потом показ или мини-сценка.\n• В конце — один вопрос по вчерашней теме.\n\nНЕДЕЛЯ 1. ГОСТЬ ОТ ВХОДА ДО ВЫХОДА\n1. Встреча гостя — первые 10 секунд, приветствие, посадка.\n2. Подача меню и первое предложение — что сказать, пока гость выбирает.\n3. Приём заказа — уточнения, повтор заказа гостю, пробивка в iiko.\n4. Подача блюд и напитков — с какой стороны, что говорим, кому что.\n5. Чек-бек — когда подойти и что спросить.\n6. Расчёт и прощание — счёт, терминал, «ждём вас снова».\n7. Резерв столов — как принять бронь, что уточнить, как держать стол.\n\nНЕДЕЛЯ 2. ПРОДАЖИ И ЗНАНИЕ МЕНЮ\n8. Рекомендации — 3 позиции, которые советуем сегодня, и почему.\n9. Допродажа — напиток к кальяну, десерт, второй чайник.\n10. Кальянная карта — крепость, вкусы, как помочь гостю выбрать.\n11. Бар — основные коктейли, чай, что подаём к кальяну.\n12. Кухня — состав топовых блюд и аллергены.\n13. Стоп-лист — как сказать гостю «нет» и сразу предложить замену.\n14. Повторение недели — мини-экзамен, вопрос каждому.\n\nНЕДЕЛЯ 3. СТАНДАРТЫ И ПОРЯДОК\n15. Внешний вид — форма, бейдж, волосы, руки.\n16. Поведение в зале — телефоны, разговоры, где стоять, когда не подходить к гостю.\n17. Менажный набор и стейшен — что должно быть и где лежит.\n18. Сервировка и чистота стола — протирка, пепельницы, уборка в процессе.\n19. Открытие смены — что чаще всего пропускают по чек-листу.\n20. Закрытие смены — что чаще всего забывают.\n21. Санузлы и чистота зала — кто, когда и как проверяет.\n\nНЕДЕЛЯ 4. СЛОЖНЫЕ СИТУАЦИИ И КОМАНДА\n22. Работа с жалобами — выслушать, извиниться, решить, позвать менеджера.\n23. Долгое ожидание — что говорить гостю, если кухня или кальян задерживаются.\n24. Конфликтный или нетрезвый гость — как себя вести, когда звать менеджера.\n25. Командная работа — помощь соседней зоне, передача стола, связь с баром и кухней.\n26. Безопасность — угли, плитка, огнетушитель; что делать при ожоге или задымлении.\n27. Разбор отзывов за неделю — что хвалили, на что жаловались.\n28. Свободная тема — что у нас хромает прямо сейчас (выбирает менеджер).\n\nСОВЕТЫ\n• Раз в неделю тему ведёт сотрудник, а не менеджер — так лучше запоминается.\n• Показ, а не рассказ: если у стандарта есть видео — включите его прямо на пятиминутке.\n', array['Управляющие'], '[]'::jsonb, 0
  from public.kb_books b
 where b.title = 'Пятиминутки'
   and not exists (select 1 from public.kb_articles a where a.book_id = b.id);
